-- Phase 2: broker catalog, MT5 accounts, symbol mapping, per-account risk profiles
-- ID convention (locked): every primary key is a uuid generated by the database.
-- Broker-side identifiers (MT5 login, broker symbol text) are ordinary columns with
-- scoped UNIQUE constraints, never primary keys or join keys.
-- No credential columns exist anywhere: MT5 passwords stay on the user's own machine.

CREATE TABLE public.brokers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  platform text NOT NULL DEFAULT 'mt5',
  default_currency text NOT NULL DEFAULT 'USD',
  min_lot numeric(10,3) NOT NULL DEFAULT 0.010,
  lot_step numeric(10,3) NOT NULL DEFAULT 0.010,
  max_lot numeric(10,3) NOT NULL DEFAULT 100.000,
  supports_hedging boolean NOT NULL DEFAULT true,
  requires_ea_bridge boolean NOT NULL DEFAULT true,
  is_active boolean NOT NULL DEFAULT true,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT brokers_code_format CHECK (code ~ '^[A-Z0-9_]{2,20}$'),
  CONSTRAINT brokers_lot_rules CHECK (min_lot > 0 AND lot_step > 0 AND max_lot >= min_lot)
);
GRANT SELECT ON public.brokers TO authenticated;
GRANT ALL ON public.brokers TO service_role;
ALTER TABLE public.brokers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "brokers readable" ON public.brokers FOR SELECT TO authenticated USING (is_active);

CREATE TABLE public.broker_accounts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  broker_id uuid NOT NULL REFERENCES public.brokers(id),
  label text NOT NULL,
  mt5_login text NOT NULL,
  mt5_server text,
  currency text NOT NULL DEFAULT 'USD',
  is_demo boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'active',
  leverage integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT broker_accounts_status CHECK (status IN ('active','paused','archived')),
  CONSTRAINT broker_accounts_login_format CHECK (mt5_login ~ '^[0-9]{3,12}$'),
  CONSTRAINT broker_accounts_label_format CHECK (label ~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{0,59}$'),
  CONSTRAINT broker_accounts_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT broker_accounts_server_format CHECK (mt5_server IS NULL OR mt5_server ~ '^[A-Za-z0-9 ._-]{0,60}$'),
  CONSTRAINT broker_accounts_leverage CHECK (leverage IS NULL OR (leverage BETWEEN 1 AND 3000)),
  UNIQUE (user_id, broker_id, mt5_login)
);
GRANT SELECT, INSERT, UPDATE ON public.broker_accounts TO authenticated;
GRANT ALL ON public.broker_accounts TO service_role;
ALTER TABLE public.broker_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own accounts read" ON public.broker_accounts FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "own accounts create (not viewer)" ON public.broker_accounts FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "own accounts update (not viewer)" ON public.broker_accounts FOR UPDATE TO authenticated
  USING (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'))
  WITH CHECK (user_id = auth.uid());

CREATE TABLE public.symbol_aliases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  broker_id uuid NOT NULL REFERENCES public.brokers(id) ON DELETE CASCADE,
  canonical_symbol text NOT NULL,
  broker_symbol text NOT NULL,
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT symbol_aliases_canonical_format CHECK (canonical_symbol ~ '^[A-Z0-9]{1,12}$'),
  CONSTRAINT symbol_aliases_broker_format CHECK (broker_symbol ~ '^[A-Za-z0-9_.#]{1,16}$'),
  UNIQUE (user_id, broker_id, broker_symbol),
  UNIQUE (user_id, broker_id, canonical_symbol, broker_symbol)
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.symbol_aliases TO authenticated;
GRANT ALL ON public.symbol_aliases TO service_role;
ALTER TABLE public.symbol_aliases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own aliases read" ON public.symbol_aliases FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "own aliases create (not viewer)" ON public.symbol_aliases FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "own aliases update (not viewer)" ON public.symbol_aliases FOR UPDATE TO authenticated
  USING (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'))
  WITH CHECK (user_id = auth.uid());
CREATE POLICY "own aliases delete (not viewer)" ON public.symbol_aliases FOR DELETE TO authenticated
  USING (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));

CREATE TABLE public.risk_profiles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  account_id uuid NOT NULL REFERENCES public.broker_accounts(id) ON DELETE CASCADE,
  name text NOT NULL DEFAULT 'default',
  max_lot numeric(10,3) NOT NULL DEFAULT 0.100,
  max_open_positions integer NOT NULL DEFAULT 5,
  max_daily_loss numeric(12,2) NOT NULL DEFAULT 100.00,
  max_drawdown_pct numeric(5,2) NOT NULL DEFAULT 10.00,
  max_exposure_pct numeric(5,2) NOT NULL DEFAULT 20.00,
  min_stop_distance_points integer NOT NULL DEFAULT 100,
  news_lock_minutes integer NOT NULL DEFAULT 15,
  allow_auto_trade boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT risk_profiles_name_format CHECK (name ~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{0,39}$'),
  CONSTRAINT risk_profiles_lot CHECK (max_lot > 0 AND max_lot <= 1000),
  CONSTRAINT risk_profiles_positions CHECK (max_open_positions BETWEEN 1 AND 200),
  CONSTRAINT risk_profiles_daily_loss CHECK (max_daily_loss > 0),
  CONSTRAINT risk_profiles_drawdown CHECK (max_drawdown_pct > 0 AND max_drawdown_pct <= 100),
  CONSTRAINT risk_profiles_exposure CHECK (max_exposure_pct > 0 AND max_exposure_pct <= 100),
  CONSTRAINT risk_profiles_stop CHECK (min_stop_distance_points BETWEEN 0 AND 100000),
  CONSTRAINT risk_profiles_news CHECK (news_lock_minutes BETWEEN 0 AND 240),
  UNIQUE (account_id, name)
);
GRANT SELECT, INSERT, UPDATE ON public.risk_profiles TO authenticated;
GRANT ALL ON public.risk_profiles TO service_role;
ALTER TABLE public.risk_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own risk profiles read" ON public.risk_profiles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "own risk profiles create (not viewer)" ON public.risk_profiles FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "own risk profiles update (not viewer)" ON public.risk_profiles FOR UPDATE TO authenticated
  USING (user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'))
  WITH CHECK (user_id = auth.uid());
CREATE UNIQUE INDEX risk_profiles_one_active ON public.risk_profiles(account_id) WHERE is_active;

-- Ownership can never be moved between tenants after the row exists.
CREATE OR REPLACE FUNCTION public.record_owner_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.user_id IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'OWNER_IMMUTABLE: ownership of an existing record cannot be transferred';
  END IF;
  RETURN NEW;
END $function$;
GRANT EXECUTE ON FUNCTION public.record_owner_guard() TO authenticated;

-- A risk profile must always belong to the same owner as the account it guards.
CREATE OR REPLACE FUNCTION public.risk_profile_owner_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF NEW.user_id IS DISTINCT FROM (
    SELECT user_id FROM public.broker_accounts WHERE id = NEW.account_id
  ) THEN
    RAISE EXCEPTION 'OWNER_MISMATCH: a risk profile must belong to the same owner as its account';
  END IF;
  RETURN NEW;
END $function$;
GRANT EXECUTE ON FUNCTION public.risk_profile_owner_guard() TO authenticated;

CREATE OR REPLACE FUNCTION public.touch_updated_at()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
GRANT EXECUTE ON FUNCTION public.touch_updated_at() TO authenticated;

-- Every account / risk-limit change lands in the tamper-proof audit trail.
CREATE OR REPLACE FUNCTION public.account_activity_audit()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE
  v_user uuid;
  v_row jsonb;
  v_action text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_user := OLD.user_id;
    v_row := to_jsonb(OLD);
    v_action := CASE WHEN TG_TABLE_NAME = 'broker_accounts' THEN 'ACCOUNT_DELETED' ELSE 'RISK_PROFILE_DELETED' END;
  ELSE
    v_user := NEW.user_id;
    v_row := to_jsonb(NEW);
    IF TG_OP = 'INSERT' THEN
      v_action := CASE WHEN TG_TABLE_NAME = 'broker_accounts' THEN 'ACCOUNT_CREATED' ELSE 'RISK_PROFILE_CREATED' END;
    ELSE
      v_action := CASE WHEN TG_TABLE_NAME = 'broker_accounts' THEN 'ACCOUNT_UPDATED' ELSE 'RISK_PROFILE_UPDATED' END;
    END IF;
  END IF;
  INSERT INTO public.audit_log(user_id, actor_id, action, entity, details)
  VALUES (v_user, auth.uid(), v_action, TG_TABLE_NAME,
    jsonb_strip_nulls(jsonb_build_object(
      'row_id', v_row->>'id',
      'label', v_row->>'label',
      'name', v_row->>'name',
      'status', v_row->>'status',
      'is_active', v_row->>'is_active'
    )));
  RETURN NULL;
END $function$;
GRANT EXECUTE ON FUNCTION public.account_activity_audit() TO authenticated;

-- A brand-new account always arrives with conservative limits attached.
CREATE OR REPLACE FUNCTION public.create_default_risk_profile()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  INSERT INTO public.risk_profiles(user_id, account_id)
  VALUES (NEW.user_id, NEW.id)
  ON CONFLICT (account_id, name) DO NOTHING;
  RETURN NEW;
END $function$;
GRANT EXECUTE ON FUNCTION public.create_default_risk_profile() TO authenticated;

CREATE TRIGGER broker_accounts_owner_guard BEFORE UPDATE ON public.broker_accounts
  FOR EACH ROW EXECUTE FUNCTION public.record_owner_guard();
CREATE TRIGGER symbol_aliases_owner_guard BEFORE UPDATE ON public.symbol_aliases
  FOR EACH ROW EXECUTE FUNCTION public.record_owner_guard();
CREATE TRIGGER risk_profiles_owner_guard BEFORE INSERT OR UPDATE ON public.risk_profiles
  FOR EACH ROW EXECUTE FUNCTION public.risk_profile_owner_guard();
CREATE TRIGGER broker_accounts_touch BEFORE UPDATE ON public.broker_accounts
  FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER risk_profiles_touch BEFORE UPDATE ON public.risk_profiles
  FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER broker_accounts_audit AFTER INSERT OR UPDATE OR DELETE ON public.broker_accounts
  FOR EACH ROW EXECUTE FUNCTION public.account_activity_audit();
CREATE TRIGGER risk_profiles_audit AFTER INSERT OR UPDATE OR DELETE ON public.risk_profiles
  FOR EACH ROW EXECUTE FUNCTION public.account_activity_audit();
CREATE TRIGGER broker_accounts_default_risk AFTER INSERT ON public.broker_accounts
  FOR EACH ROW EXECUTE FUNCTION public.create_default_risk_profile();